typedef float rational_t;

class vector4d
{
public:
  rational_t x, y, z, w;

  inline rational_t& operator[](int i)
  { return (&x)[i]; }

  inline const rational_t& operator[](int i) const
  { return (&x)[i]; }
};

class matrix4x4
{
public:
  typedef rational_t T;
  typedef vector4d row;

  row x __attribute__((aligned(16)));
  row y;
  row z;
  row w;

  inline matrix4x4() {}

  inline const row& operator[](int i) const
  { return (&x)[i]; }

  inline row& operator[](int i)
  { return (&x)[i]; }

  matrix4x4 Cof() __asm__("Cof__9matrix4x4");
  T cofactor(int, int) const __asm__("cofactor__C9matrix4x4ii");
};

matrix4x4 matrix4x4::Cof()
{
  matrix4x4 t;

  for(int i = 0; i < 4; ++i)
  {
    for(int j = 0; j < 4; ++j)
      t[i][j] = this->cofactor(i, j);
  }

  return t;
}
